WITH lines AS (SELECT id, host, log_ts, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, v) SELECT id, host, log_ts, latency_ms, key, v, CORR(latency_ms, status_code) OVER (PARTITION BY host) AS corr_latency_ms_status_code, ROW_NUMBER() OVER (ORDER BY log_ts, id, key) AS row_seq, ROW_NUMBER() OVER (PARTITION BY key ORDER BY status_code, id, key) AS event_seq, MIN(latency_ms) OVER (PARTITION BY TO_DATE(log_ts), host) AS log_ts_to_date_min_latency_ms, SUM(status_code) OVER (PARTITION BY key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS status_code_sum_15m FROM lines;
